import time
import numpy as np
from scipy.optimize import minimize

N = 16
I, J = np.triu_indices(N, 1)
M = len(I)


def score(P):
    P = np.asarray(P, dtype=float)
    if P.shape != (N, 2) or not np.all(np.isfinite(P)):
        return np.inf
    d2 = ((P[I] - P[J]) ** 2).sum(1)
    lo = d2.min()
    if lo <= 1e-12:
        return np.inf
    return d2.max() / lo


def energy(P):
    d2 = ((P[I] - P[J]) ** 2).sum(1)
    lo = d2.min()
    if lo <= 1e-12:
        return np.inf
    return np.log(d2.max() / lo)


def anneal(P, rng, steps, T0, T1):
    # Metropolis annealing on log(max/min) with step size tied to temperature.
    P = P.copy()
    E = energy(P)
    best, bestE = P.copy(), E
    for k in range(steps):
        T = T0 * (T1 / T0) ** (k / steps)
        scale = np.sqrt(((P[I] - P[J]) ** 2).sum(1).max())
        s = (0.25 * T + 0.002) * scale
        Q = P.copy()
        if rng.random() < 0.6:
            i = rng.integers(N)
            Q[i] += rng.normal(0, s, 2)
        else:
            Q += rng.normal(0, s * 0.3, (N, 2))
        Eq = energy(Q)
        if Eq <= E or rng.random() < np.exp(-(Eq - E) / T):
            P, E = Q, Eq
            if E < bestE:
                best, bestE = P.copy(), E
    return best


def cons_fun(z):
    P = z[:-1].reshape(N, 2)
    d = P[I] - P[J]
    d2 = (d * d).sum(1)
    return np.concatenate([d2 - 1.0, z[-1] - d2])


def cons_jac(z):
    P = z[:-1].reshape(N, 2)
    d = P[I] - P[J]
    G = np.zeros((M, 2 * N + 1))
    rows = np.arange(M)[:, None]
    cols = np.arange(2)
    G[rows, 2 * I[:, None] + cols] = 2 * d
    G[rows, 2 * J[:, None] + cols] = -2 * d
    H = -G
    H[:, -1] = 1.0
    return np.vstack([G, H])


def polish(P):
    # Single SLSQP pass on the epigraph form, only used to sharpen the annealed result.
    d2 = ((P[I] - P[J]) ** 2).sum(1)
    P = P / np.sqrt(max(d2.min(), 1e-12))
    d2 = ((P[I] - P[J]) ** 2).sum(1)
    z0 = np.concatenate([P.ravel(), [d2.max()]])
    obj_g = np.zeros_like(z0)
    obj_g[-1] = 1.0
    try:
        res = minimize(
            lambda z: z[-1], z0, jac=lambda z: obj_g,
            method="SLSQP",
            constraints=[{"type": "ineq", "fun": cons_fun, "jac": cons_jac}],
            options={"maxiter": 200, "ftol": 1e-13},
        )
        return res.x[:-1].reshape(N, 2)
    except Exception:
        return None


def solve(time_limit, best_so_far):
    start = time.time()
    deadline = start + 0.4 * min(time_limit, 20)
    rng = np.random.default_rng()

    best, best_s = None, np.inf
    if best_so_far is not None:
        s = score(best_so_far)
        if np.isfinite(s):
            best = np.array(best_so_far, dtype=float)
            best_s = s

    # Annealing chains from random or perturbed-best starts, reserve time for polish.
    while time.time() < deadline - 0.8:
        if best is None or rng.random() < 0.5:
            P0 = rng.uniform(-1, 1, size=(N, 2))
        else:
            P0 = best + rng.normal(0, 0.05, size=(N, 2))
        P = anneal(P0, rng, steps=15000, T0=0.3, T1=1e-4)
        s = score(P)
        if s < best_s:
            best, best_s = P, s

    if best is not None:
        Q = polish(best)
        if Q is not None:
            s = score(Q)
            if s < best_s:
                best, best_s = Q, s

    if best is None or not np.isfinite(best_s):
        return np.array([(i, j) for i in range(4) for j in range(4)], dtype=float)
    return best


if __name__ == "__main__":
    P = solve(5, None)
    assert P.shape == (N, 2)
    assert score(P) < 18.0
    print(score(P))

import time
import numpy as np
from scipy.optimize import minimize

N = 16
I, J = np.triu_indices(N, 1)
M = len(I)


def score(P):
    P = np.asarray(P, dtype=float)
    if P.shape != (N, 2) or not np.all(np.isfinite(P)):
        return np.inf
    d2 = ((P[I] - P[J]) ** 2).sum(1)
    lo = d2.min()
    if lo <= 1e-12:
        return np.inf
    return d2.max() / lo


def normalize(P):
    d2 = ((P[I] - P[J]) ** 2).sum(1)
    lo = d2.min()
    if lo <= 1e-12:
        return None
    return P / np.sqrt(lo)


def energy(P):
    d2 = ((P[I] - P[J]) ** 2).sum(1)
    lo = d2.min()
    if lo <= 1e-12:
        return np.inf
    return np.log(d2.max() / lo)


def anneal(P, rng, steps, T0, T1):
    # Metropolis annealing on log(max/min); step size scales with temperature.
    P = P.copy()
    E = energy(P)
    best, bestE = P.copy(), E
    for k in range(steps):
        T = T0 * (T1 / T0) ** (k / steps)
        scale = np.sqrt(((P[I] - P[J]) ** 2).sum(1).max())
        s = (0.25 * T + 0.002) * scale
        Q = P.copy()
        if rng.random() < 0.6:
            Q[rng.integers(N)] += rng.normal(0, s, 2)
        else:
            Q += rng.normal(0, 0.3 * s, (N, 2))
        Eq = energy(Q)
        if Eq <= E or rng.random() < np.exp(-(Eq - E) / T):
            P, E = Q, Eq
            if E < bestE:
                best, bestE = P.copy(), E
    return best


def cons_fun(z):
    P = z[:-1].reshape(N, 2)
    diff = P[I] - P[J]
    d2 = (diff ** 2).sum(1)
    return np.concatenate([d2 - 1.0, z[-1] - d2])


def cons_jac(z):
    P = z[:-1].reshape(N, 2)
    diff = P[I] - P[J]
    jac = np.zeros((2 * M, 2 * N + 1))
    rows = np.arange(M)
    for c in range(2):
        jac[rows, 2 * I + c] = 2 * diff[:, c]
        jac[rows, 2 * J + c] = -2 * diff[:, c]
    jac[M:, :2 * N] = -jac[:M, :2 * N]
    jac[M:, -1] = 1.0
    return jac


def obj_grad(z):
    g = np.zeros_like(z)
    g[-1] = 1.0
    return g


def local_opt(P):
    # Epigraph SLSQP: min D s.t. pair d^2 >= 1 and pair d^2 <= D.
    P = normalize(P)
    if P is None:
        return None
    d2 = ((P[I] - P[J]) ** 2).sum(1)
    z0 = np.concatenate([P.ravel(), [d2.max()]])
    try:
        res = minimize(
            lambda z: z[-1], z0, jac=obj_grad, method="SLSQP",
            constraints=[{"type": "ineq", "fun": cons_fun, "jac": cons_jac}],
            options={"maxiter": 300, "ftol": 1e-13},
        )
    except Exception:
        return None
    return normalize(res.x[:-1].reshape(N, 2))


def solve(time_limit, best_so_far):
    start = time.time()
    # Stay well inside the hard kill window.
    deadline = start + 0.35 * min(time_limit, 20)
    rng = np.random.default_rng()

    best, best_s = None, np.inf
    if best_so_far is not None:
        s = score(best_so_far)
        if np.isfinite(s):
            best, best_s = np.array(best_so_far, dtype=float), s

    def consider(Q):
        nonlocal best, best_s
        if Q is None:
            return
        s = score(Q)
        if s < best_s - 1e-12:
            best, best_s = Q.copy(), s

    while time.time() < deadline:
        r = rng.random()
        if best is None or r < 0.3:
            # Global exploration: short anneal from random, then local polish.
            P0 = anneal(rng.uniform(-1, 1, (N, 2)), rng, steps=4000, T0=0.3, T1=1e-4)
            consider(local_opt(P0))
        else:
            # Basin hopping around the incumbent.
            sigma = rng.choice([0.05, 0.15, 0.3])
            P0 = best + rng.normal(0, sigma, (N, 2))
            if rng.random() < 0.3:
                k = rng.integers(N)
                P0[k] = rng.uniform(best.min(0), best.max(0))
            consider(local_opt(P0))

    if best is None:
        return np.array([(i, j) for i in range(4) for j in range(4)], dtype=float)
    return best


if __name__ == "__main__":
    P = solve(5, None)
    assert P.shape == (N, 2)
    assert score(P) < 18.0
    print(score(P))
